{"read_file": "import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_account_dict, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
FACTOR_WEIGHTS = {"miner_2_trend_acceleration_20_60": .22, "miner_3_clv_1d": .21, "peer_median_leadlag_5d": .19, "short_term_reversal_5d": .15, "miner_2_risk_adjusted_momentum_20d": .14, "volume_confirmed_contrarian_5d": .09}
MIN_W, MAX_W, REBALANCE_DAYS = .015, .16, 10
last_date = None

def rank(x):
    out = {s: .5 for s in UNIVERSE}; good = sorted((s, float(v)) for s, v in x.items() if np.isfinite(v))
    if len(good) > 1:
        for i, (s, _) in enumerate(good): out[s] = (i + 1.) / len(good)
    return out

def box_weights(raw):
    w = {s: max(1e-9, float(raw.get(s, 0))) for s in UNIVERSE}
    for _ in range(20):
        z = sum(w.values()); w = {s: v / z for s, v in w.items()}
        low = [s for s in UNIVERSE if w[s] < MIN_W]; high = [s for s in UNIVERSE if w[s] > MAX_W]
        if not low and not high: break
        fixed = {s: MIN_W for s in low}; fixed.update({s: MAX_W for s in high})
        free = [s for s in UNIVERSE if s not in fixed]; rem = 1. - sum(fixed.values()); base = sum(w[s] for s in free) or 1.
        w = {s: fixed.get(s, rem * w[s] / base) for s in UNIVERSE}
    z = sum(w.values()); return {s: float(w[s] / z) for s in UNIVERSE}

@register_hook
def cross_asset_strategy():
    global last_date
    account = get_account_dict(); data = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=100)
        if df is None or len(df) < 65: continue
        df = df.sort_values("date").reset_index(drop=True)
        c = np.asarray(df.close, float); h = np.asarray(df.high, float); l = np.asarray(df.low, float); r = c[1:] / np.maximum(c[:-1], 1e-12) - 1
        vol = np.asarray(df.volume, float) if "volume" in df else np.ones(len(c)); data[s] = (c, h, l, r, vol, str(df.iloc[-1].date))
    if len(data) < 12: return
    decision = max(x[5] for x in data.values())
    if last_date is not None:
        try:
            if (np.datetime64(decision) - np.datetime64(last_date)) / np.timedelta64(1, "D") < REBALANCE_DAYS: return
        except Exception: return
    trend, clv, peer, reversal, mom, contrarian, invvol, five = {}, {}, {}, {}, {}, {}, {}, {}
    for s, (c, h, l, r, volume, _) in data.items():
        vol20 = max(float(np.std(r[-20:])), .008); invvol[s] = 1. / vol20
        trend[s] = (c[-1] / c[-21] - 1.) - .5 * (c[-1] / c[-61] - 1.)
        clv[s] = float((2*c[-1] - h[-1] - l[-1]) / max(h[-1]-l[-1], 1e-12)); five[s] = c[-1] / c[-6] - 1.
        reversal[s] = -float(np.mean(r[-5:])); mom[s] = float((c[-1] / c[-21] - 1.) / (vol20 + .01))
        vr = float(volume[-5:].mean() / max(volume[-20:].mean(), 1e-12)); contrarian[s] = -float(np.mean(r[-5:])) * min(vr, 2.)
    med = float(np.median(list(five.values()))); peer = {s: five[s] - med for s in five}
    vals = {"miner_2_trend_acceleration_20_60": rank(trend), "miner_3_clv_1d": rank(clv), "peer_median_leadlag_5d": rank(peer), "short_term_reversal_5d": rank(reversal), "miner_2_risk_adjusted_momentum_20d": rank(mom), "volume_confirmed_contrarian_5d": rank(contrarian)}
    score = {s: sum(FACTOR_WEIGHTS[f] * vals[f].get(s, .5) for f in FACTOR_WEIGHTS) for s in UNIVERSE}
    if "SPX" in data and data["SPX"][0][-1] < data["SPX"][0][-21]:
        for s in ("XAU", "US10Y", "CN10Y"): score[s] += .14
        for s in ("BTC", "ETH", "WTI"): score[s] = max(.05, score[s] - .07)
    mean_iv = np.mean(list(invvol.values())); raw = {s: max(score[s], .01) * (.78 + .22 * invvol[s] / max(mean_iv, 1e-12)) for s in UNIVERSE}; weights = box_weights(raw)
    mu, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-12); forecast_returns = {s: float(.01 * (score[s] - mu) / sd) for s in UNIVERSE}
    try:
        ens = json.loads((Path(__file__).parent / "factors" / "factor_ensemble.json").read_text()); factor_ids = [str(x["factor_id"]) for x in ens.get("selected_factors", [])[:10]]
    except Exception: factor_ids = list(FACTOR_WEIGHTS)
    rebalance_to_weights(weights, forecast_returns=forecast_returns, factor_ids=factor_ids, horizon_days=10); last_date = decision
"}

