from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = [
    ("miner_1_volatility_compression_10d_v1", .22, 1),
    ("miner_3_defensive_volatility_quality_10d", .22, 1),
    ("relative_lowvolatility_10d", .15, 1),
    ("relative_residual_reversal_10d", .11, 1),
    ("miner_2_20301114_market_residual_reversal_20d", .10, 1),
    ("miner_1_volume_confirmed_momentum20_10d", .07, 1),
    ("miner_1_relative_strength_quality_10d", .07, 1),
    ("miner_1_consistency_volscaled_momentum20_10d", .06, 1),
]
last_decision = -10**9


def rank(v):
    good = sorted(x for x in v.values() if np.isfinite(x))
    out = {s: .5 for s in UNIVERSE}
    if len(good) > 1:
        for s, x in v.items():
            if np.isfinite(x):
                out[s] = np.searchsorted(good, x, side="right") / len(good)
    return out


def bounded(score):
    # Iterative projection to 2%-15% per asset, then exact normalization.
    w = {s: max(float(score[s]), 1e-9) for s in UNIVERSE}
    for _ in range(30):
        z = sum(w.values())
        n = {s: w[s] / z for s in UNIVERSE}
        fixed = {s: (.02 if n[s] < .02 else .15) for s in UNIVERSE
                 if n[s] < .02 or n[s] > .15}
        if not fixed:
            return n
        free = [s for s in UNIVERSE if s not in fixed]
        rem = 1 - sum(fixed.values())
        den = sum(n[s] for s in free)
        w = dict(fixed)
        for s in free:
            w[s] = rem * n[s] / max(den, 1e-12)
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def strategy():
    global last_decision
    data = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=340)
        if df is None or len(df) < 270:
            continue
        c = np.asarray(df.sort_values("date")["close"], dtype=float)
        vol = np.asarray(df.sort_values("date")["volume"], dtype=float) if "volume" in df else np.ones(len(c))
        if np.all(np.isfinite(c)) and np.all(c > 0):
            data[s] = (np.diff(np.log(c)), vol)
    if len(data) < 10:
        return
    end = min(len(x[0]) for x in data.values()) - 1
    if end < 260 or end - last_decision < 10:
        return
    ret = {s: x[0] for s, x in data.items()}
    r10 = {s: x[end-10:end].sum() for s, x in ret.items()}
    r20 = {s: x[end-20:end].sum() for s, x in ret.items()}
    r60 = {s: x[end-60:end].sum() for s, x in ret.items()}
    v10 = {s: max(np.std(x[end-10:end]), .008) for s, x in ret.items()}
    v20 = {s: max(np.std(x[end-20:end]), .008) for s, x in ret.items()}
    med10, med20 = np.median(list(v10.values())), np.median(list(v20.values()))
    medr10, medr20 = np.median(list(r10.values())), np.median(list(r20.values()))
    vals = {f: {} for f, _, _ in ENSEMBLE}
    for s, x in ret.items():
        prior = max(np.std(x[end-30:end-10]), .008)
        longv = max(np.std(x[end-60:end]), .008)
        hist = [np.std(x[j-10:j]) for j in range(max(10, end-100), end)]
        hmed = max(float(np.median(hist)), .008)
        _, volume = data[s]
        lv = np.log(np.maximum(volume, 1e-12))
        a = max(0, end-80)
        surprise = float(np.clip(lv[end-20:end].mean() - lv[a:end-20].mean(), -2, 2))
        vals["miner_1_volatility_compression_10d_v1"][s] = -(v10[s] / longv - 1)
        vals["miner_3_defensive_volatility_quality_10d"][s] = -(v20[s] / hmed) - .5 * (v20[s] / prior - 1)
        vals["relative_lowvolatility_10d"][s] = -np.log(v20[s] / med20)
        vals["relative_residual_reversal_10d"][s] = -(r10[s] - medr10) / v10[s]
        vals["miner_2_20301114_market_residual_reversal_20d"][s] = -(r20[s] - medr20) / v20[s]
        vals["miner_1_volume_confirmed_momentum20_10d"][s] = r20[s] * (1 + .25 * surprise)
        vals["miner_1_relative_strength_quality_10d"][s] = (r20[s] - medr20) / longv
        vals["miner_1_consistency_volscaled_momentum20_10d"][s] = r20[s] / max(np.sum(np.abs(x[end-20:end])), .008)
    score = {s: 0.0 for s in UNIVERSE}
    for fid, wt, direction in ENSEMBLE:
        rr = rank(vals[fid])
        for s in UNIVERSE:
            score[s] += wt * direction * rr[s]
    breadth = np.mean([r60[s] > 0 for s in ret])
    if breadth < .45:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += .08
    floor = min(score.values())
    target = bounded({s: score[s] - floor + .05 for s in UNIVERSE})
    avg, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-8)
    forecast = {s: float(.006 * (score[s] - avg) / sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[f for f, _, _ in ENSEMBLE], horizon_days=10)
    last_decision = end
